CREATE TABLE "accounts" ("id" TEXT PRIMARY KEY, "roblox_user_id" TEXT NOT NULL UNIQUE, "username" TEXT NOT NULL, "display_name" TEXT NOT NULL, "avatar_url" TEXT, "online_status" TEXT NOT NULL DEFAULT 'offline', "last_online_at" TIMESTAMP(3), "presence_checked_at" TIMESTAMP(3), "last_scan_at" TIMESTAMP(3), "scan_status" TEXT NOT NULL DEFAULT 'pending', "level" INTEGER NOT NULL DEFAULT 0, "beli" BIGINT NOT NULL DEFAULT 0, "fragments" BIGINT NOT NULL DEFAULT 0, "current_fruit" TEXT, "race" TEXT, "sea" INTEGER NOT NULL DEFAULT 1, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "account_items" ("id" TEXT PRIMARY KEY, "account_id" TEXT NOT NULL REFERENCES "accounts"("id") ON DELETE CASCADE, "item_key" TEXT NOT NULL, "item_name" TEXT NOT NULL, "category" TEXT NOT NULL, "quantity" INTEGER NOT NULL DEFAULT 0, "owned" BOOLEAN NOT NULL DEFAULT false, "permanent" BOOLEAN NOT NULL DEFAULT false, "mastery" INTEGER, "metadata" JSONB, "updated_at" TIMESTAMP(3) NOT NULL, UNIQUE("account_id", "item_key"));
CREATE TABLE "scan_logs" ("id" TEXT PRIMARY KEY, "account_id" TEXT NOT NULL REFERENCES "accounts"("id") ON DELETE CASCADE, "started_at" TIMESTAMP(3) NOT NULL, "finished_at" TIMESTAMP(3), "status" TEXT NOT NULL, "error_message" TEXT, "raw_snapshot" JSONB);
